		if _, ok := contractPaths[p]; ok {
			return true
		}
		for _, e := range c.extensions {
			if e.name == p {
				return true
			}
		}
		for _, on := range c.onAppend {
			if "Append"+"/"+on.name == p {
				return true
			}
		}
		for _, on := range c.onSubscribe {
			if "Subscribe"+"/"+on.name == p {
				return true
			}
		}
		return false
